// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";

/// @title MetricOmmSwapInputs
/// @notice Shared swap input amount casts for routers and quoters.
library MetricOmmSwapInputs {
  using SafeCast for int256;
  using SafeCast for uint256;

  uint128 internal constant MAX_INT128_AS_UINT128 = uint128(type(int128).max);

  /// @notice Provided unsigned amount does not fit in int128.
  error AmountTooLarge(uint128 amount);
  /// @notice Deltas do not match expected exact-in/out shape.
  error InvalidSwapDeltas();

  function asAmountSpecifiedIn(uint128 amountIn) internal pure returns (int128 amountSpecified) {
    amountSpecified = toInt128(amountIn);
  }

  function asAmountSpecifiedOut(uint128 amountOut) internal pure returns (int128 amountSpecified) {
    amountSpecified = -toInt128(amountOut);
  }

  function toInt128(uint128 amount) internal pure returns (int128) {
    if (amount > MAX_INT128_AS_UINT128) revert AmountTooLarge(amount);
    // forge-lint: disable-next-line(unsafe-typecast)
    return int128(amount);
  }

  function toUint128(uint256 amount) internal pure returns (uint128) {
    if (amount > MAX_INT128_AS_UINT128) revert AmountTooLarge(uint128(amount));
    // forge-lint: disable-next-line(unsafe-typecast)
    return uint128(amount);
  }

  function int128ToUint128(int128 amount) internal pure returns (uint128) {
    return int256(amount).toUint256().toUint128();
  }

  function asAmountSpecifiedFromPositive(int256 amount) internal pure returns (int128 amountSpecified) {
    if (amount <= 0) revert InvalidSwapDeltas();
    if (amount > type(int128).max) revert AmountTooLarge(uint128(uint256(amount)));
    return negInt128(amount);
  }

  function negInt128(int256 amount) internal pure returns (int128) {
    return -amount.toInt128();
  }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

/// @title MetricOmmSwapResults
/// @notice Shared swap delta result helpers for routers and quoters.
library MetricOmmSwapResults {
  /// @notice Deltas do not match expected exact-in/out shape.
  error InvalidSwapDeltas();

  function extractAmountOut(bool zeroForOne, int128 amount0Delta, int128 amount1Delta) internal pure returns (int128) {
    return zeroForOne ? -amount1Delta : -amount0Delta;
  }

  function extractAmountIn(bool zeroForOne, int128 amount0Delta, int128 amount1Delta) internal pure returns (int128) {
    return zeroForOne ? amount0Delta : amount1Delta;
  }

  function getPositiveAmount(int256 amount0Delta, int256 amount1Delta) internal pure returns (int256 amount) {
    if (amount0Delta > 0 && amount1Delta < 0) {
      // forge-lint: disable-next-line(unsafe-typecast)
      return amount0Delta;
    }
    if (amount1Delta > 0 && amount0Delta < 0) {
      // forge-lint: disable-next-line(unsafe-typecast)
      return amount1Delta;
    }
    return type(int256).min;
  }

  function extractPositiveAmount(int256 amount0Delta, int256 amount1Delta) internal pure returns (int256 amount) {
    amount = getPositiveAmount(amount0Delta, amount1Delta);
    if (amount == type(int256).min) revert InvalidSwapDeltas();
    return amount;
  }

  function hasValidExactInDeltas(bool zeroForOne, int128 amount0Delta, int128 amount1Delta)
    internal
    pure
    returns (bool)
  {
    if (zeroForOne) return amount0Delta > 0 && amount1Delta < 0;
    return amount1Delta > 0 && amount0Delta < 0;
  }

  function extractAmountInAndOut(bool zeroForOne, int128 amount0Delta, int128 amount1Delta)
    internal
    pure
    returns (uint256 amountIn, uint256 amountOut)
  {
    if (!hasValidExactInDeltas(zeroForOne, amount0Delta, amount1Delta)) revert InvalidSwapDeltas();
    return toUnsignedAmounts(zeroForOne, amount0Delta, amount1Delta);
  }

  function toUnsignedAmounts(bool zeroForOne, int128 amount0Delta, int128 amount1Delta)
    internal
    pure
    returns (uint256 inputAmount, uint256 outputAmount)
  {
    if (zeroForOne) {
      // forge-lint: disable-next-line(unsafe-typecast)
      inputAmount = uint256(uint128(amount0Delta));
      // forge-lint: disable-next-line(unsafe-typecast)
      outputAmount = uint256(uint128(-amount1Delta));
    } else {
      // forge-lint: disable-next-line(unsafe-typecast)
      inputAmount = uint256(uint128(amount1Delta));
      // forge-lint: disable-next-line(unsafe-typecast)
      outputAmount = uint256(uint128(-amount0Delta));
    }
  }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import {IMetricOmmSimpleRouter} from "../interfaces/IMetricOmmSimpleRouter.sol";

/// @title TransientCallbackPool
/// @notice EIP-1153 transient slot for swap callback context.
/// @dev Layout: bits 0-159 pool, bits 160-167 callback mode, bits 168+ tradesLeft (exact-output recursion only).
library TransientCallbackPool {
  uint256 private constant T_SLOT = 0;
  uint256 private constant T_AMOUNT_IN_SLOT = 1;
  uint256 private constant T_PAYER_SLOT = 2;
  uint256 private constant T_TOKEN_TO_PAY_SLOT = 3;
  uint256 private constant CALLBACK_MODE_OFFSET = 160;
  uint256 private constant TRADES_LEFT_OFFSET = 168;
  uint256 private constant CALLBACK_MODE_MASK = 0xff;

  function update(address pool, uint256 tradesLeft) internal {
    uint256 callbackMode = getCallbackMode();
    uint256 value = uint256(uint160(pool));
    value |= (uint256(callbackMode) << CALLBACK_MODE_OFFSET);
    value |= tradesLeft << TRADES_LEFT_OFFSET;
    _tstore(T_SLOT, value);
  }

  function set(address pool, uint8 callbackMode, uint256 tradesLeft, address payer, address tokenToPay) internal {
    uint256 value = uint256(uint160(pool));
    value |= (uint256(callbackMode) << CALLBACK_MODE_OFFSET);
    value |= tradesLeft << TRADES_LEFT_OFFSET;
    _tstore(T_SLOT, value);
    _tstoreAddress(T_PAYER_SLOT, payer);
    _tstoreAddress(T_TOKEN_TO_PAY_SLOT, tokenToPay);
  }

  function set(address pool, uint8 callbackMode, address payer, address tokenToPay) internal {
    uint256 value = uint256(uint160(pool));
    value |= (uint256(callbackMode) << CALLBACK_MODE_OFFSET);
    _tstore(T_SLOT, value);
    _tstoreAddress(T_PAYER_SLOT, payer);
    _tstoreAddress(T_TOKEN_TO_PAY_SLOT, tokenToPay);
  }

  function getPool() internal view returns (address pool) {
    // forge-lint: disable-next-line(unsafe-typecast)
    pool = address(uint160(_tload(T_SLOT)));
  }

  function getCallbackMode() internal view returns (uint8 callbackMode) {
    // forge-lint: disable-next-line(unsafe-typecast)
    callbackMode = uint8((_tload(T_SLOT) >> CALLBACK_MODE_OFFSET) & CALLBACK_MODE_MASK);
  }

  function getTradesLeft() internal view returns (uint8 tradesLeft) {
    // forge-lint: disable-next-line(unsafe-typecast)
    tradesLeft = uint8(_tload(T_SLOT) >> TRADES_LEFT_OFFSET);
  }

  function setAmountIn(uint256 amountIn) internal {
    _tstore(T_AMOUNT_IN_SLOT, amountIn);
  }

  function getAmountIn() internal view returns (uint256 amountIn) {
    amountIn = _tload(T_AMOUNT_IN_SLOT);
  }

  function getPayer() internal view returns (address payer) {
    payer = _tloadAddress(T_PAYER_SLOT);
  }

  function getTokenToPay() internal view returns (address tokenToPay) {
    tokenToPay = _tloadAddress(T_TOKEN_TO_PAY_SLOT);
  }

  function clear() internal {
    _tstore(T_SLOT, 0);
    _tstore(T_AMOUNT_IN_SLOT, 0);
    _tstoreAddress(T_PAYER_SLOT, address(0));
    _tstoreAddress(T_TOKEN_TO_PAY_SLOT, address(0));
  }

  function requireCaller(address caller) internal view {
    if (caller != getPool()) revert IMetricOmmSimpleRouter.InvalidCallbackCaller();
  }

  function _tload(uint256 slot) private view returns (uint256 value) {
    assembly ("memory-safe") {
      value := tload(slot)
    }
  }

  function _tstore(uint256 slot, uint256 value) private {
    assembly ("memory-safe") {
      tstore(slot, value)
    }
  }

  function _tloadAddress(uint256 slot) private view returns (address value) {
    // forge-lint: disable-next-line(unsafe-typecast)
    value = address(uint160(_tload(slot)));
  }

  function _tstoreAddress(uint256 slot, address value) private {
    _tstore(slot, uint256(uint160(value)));
  }
}

